	private static Bitmap LoadEmbeddedBitmap(string resourceName)
	{
		using Stream stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(resourceName) ?? throw new InvalidOperationException("Missing embedded image: " + resourceName);
		using Image image = Image.FromStream(stream);
		return new Bitmap(image);
	}

