	private void boxDragEnter(object sender, DragEventArgs e, string 文件名字)
	{
		if (!e.Data.GetDataPresent(DataFormats.FileDrop))
		{
			e.Effect = DragDropEffects.None;
			return;
		}
		string[] array = (string[])e.Data.GetData(DataFormats.FileDrop);
		if (array.Length == 1 && Path.GetExtension(array[0]).ToLower() == ".list")
		{
			if (Path.GetFileName(array[0]) != 文件名字)
			{
				e.Effect = DragDropEffects.None;
			}
			else
			{
				e.Effect = DragDropEffects.Copy;
			}
		}
		else
		{
			e.Effect = DragDropEffects.None;
		}
	}

	private void boxDragDrop(object sender, DragEventArgs e, string 文件名字, int 图标位置, int 叠加位置)
	{
		if (!e.Data.GetDataPresent(DataFormats.FileDrop))
		{
			return;
		}
		string path = ((string[])e.Data.GetData(DataFormats.FileDrop))[0];
		if (Path.GetFileName(path) != 文件名字)
		{
			MessageBox.Show("拖入文件有误，无法读取", "错误", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			return;
		}
		try
		{
			List<道具数据> list = ParseListFile(path, 图标位置, 叠加位置);
			switch (文件名字)
			{
			case "charge_item.list":
				charge_item_box.Text = list.ToStrings();
				break;
			case "special_item.list":
				special_item_box.Text = list.ToStrings();
				break;
			case "medicine.list":
				medicine_box.Text = list.ToStrings();
				break;
			case "task_item.list":
				task_item_box.Text = list.ToStrings();
				break;
			}
			MessageBox.Show($"成功读取 {list.Count} 条数据！", "提示", MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
		}
		catch (Exception ex)
		{
			MessageBox.Show("读取文件失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Hand);
		}
	}

	private List<道具数据> ParseListFile(string path, int 图标位置, int 叠加位置)
	{
		List<道具数据> list = new List<道具数据>();
		string[] array = File.ReadAllLines(path, Encoding.GetEncoding(936));
		for (int i = 0; i < array.Length; i++)
		{
			if (!string.IsNullOrWhiteSpace(array[i]) && !array[i].StartsWith("#"))
			{
				string[] array2 = array[i].Replace(" ", string.Empty).Split(',');
				if (array2.Length > 图标位置 && array2.Length > 叠加位置 && int.TryParse(array2[图标位置], out var result) && int.TryParse((叠加位置 > 0) ? array2[叠加位置] : ((叠加位置 == 0) ? "0" : "1"), out var result2))
				{
					list.Add(new 道具数据
					{
						名字 = array2[0],
						图标 = result,
						叠加 = result2
					});
				}
			}
		}
		return list;
	}

	public async void 在线日志线程()
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		await Task.Delay(1);
		日志记录文本框.Invoke((MethodInvoker)async delegate
		{
			while (true)
			{
				if (base.Visible)
				{
					if (日志记录文本框.Lines.Length > 100)
					{
						日志记录文本框.Text = string.Empty;
					}
					if (全局变量类.日志组.TryDequeue(out var result))
					{
						日志记录文本框.Text = result + "\r\n" + 日志记录文本框.Text;
					}
					await Task.Delay(10);
				}
			}
		});
	}

