	private void 界面组件赋值(int 配置类型)
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		Invoke((MethodInvoker)delegate
		{
			if (配置类型 == 35)
			{
				网关组件赋值();
			}
			else if (配置类型 == 40)
			{
				黑名单组件赋值();
			}
			else if (配置类型 == 47)
			{
				奇宝斋组件赋值();
			}
			else if (配置类型 == 48)
			{
				妖族化形组件赋值();
			}
