	[Rpc(hash = 10068)]
	public void 返回角色监控列表(string value, bool 是否结束)
	{
		try
		{
			Invoke((MethodInvoker)delegate
			{
				刷新角色文本提示.Text = ((!是否结束) ? "正在加载列表..." : "加载完成！");
				int result2;
				if (是否结束)
				{
					if (int.TryParse(value, out var result))
					{
						刷新角色列表事件();
						刷新发货角色列表事件();
						NDebug.Log($"总注册人数：{result}  当前在线人数：{Singleton<全局变量类>.I.角色列表.Count((角色汇总类 x) => x.是否在线)}  当前在线IP：{(from role in Singleton<全局变量类>.I.角色列表.FindAll((角色汇总类 x) => x.是否在线)
							select role.IP).Distinct().Count()}");
					}
				}
				else if (!string.IsNullOrWhiteSpace(value) && !int.TryParse(value, out result2))
				{
					角色汇总类 item = JsonConvert.DeserializeObject<角色汇总类>(value);
					Singleton<全局变量类>.I.角色列表.Add(item);
				}
			});
		}
		catch (Exception ex)
		{
			NDebug.LogError($"返回角色监控列表-报错：{ex.Message}（{ex.StackTrace}）");
		}
		角色监控_刷新按钮.Enabled = true;
	}

	public void 刷新角色列表事件(string 查询账号 = "", string 查询名称 = "")
	{
		try
		{
			if (!base.IsHandleCreated)
			{
				return;
			}
			Invoke((MethodInvoker)delegate
			{
				List<角色汇总类> list = Singleton<全局变量类>.I.角色列表;
				if (!string.IsNullOrWhiteSpace(查询账号))
				{
					list = list.FindAll((角色汇总类 x) => Singleton<ByteAPI>.I.寻找文本(x.账号, 查询账号));
				}
				if (!string.IsNullOrWhiteSpace(查询名称))
				{
					list = list.FindAll((角色汇总类 x) => Singleton<ByteAPI>.I.寻找文本(x.昵称, 查询名称));
				}
				if (监控_只看在线.Checked)
				{
					list = list.FindAll((角色汇总类 x) => x.是否在线);
				}
				list.Sort();
				for (int num = 0; num < list.Count; num++)
				{
					角色监控_角色列表.Rows.Add(list[num].GID, list[num].账号, list[num].昵称, list[num].等级, (AllEnums.性别Type)list[num].性别, (AllEnums.门派Type)list[num].五行, list[num].所在地图名字, list[num].金元宝, list[num].银元宝, list[num].金钱, list[num].奇宝点, list[num].南极点, list[num].累充点, list[num].is指定会员, list[num].is战斗中, list[num].IP, list[num].Mac, list[num].历史QQ, list[num].上线时间, list[num].离线时间);
				}
			});
		}
		catch (Exception ex)
		{
			NDebug.LogError($"刷新角色列表事件-报错：{ex.Message}（{ex.StackTrace}）");
		}
	}

