	private void 在线发货_角色列表_TextUpdate(object sender, EventArgs e)
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		if (string.IsNullOrWhiteSpace(在线发货_角色列表.Text))
		{
			在线发货_角色列表.Items.Clear();
			在线发货_角色列表.Items.Add("所有在线玩家");
			for (int i = 0; i < Singleton<全局变量类>.I.角色列表.Count; i++)
			{
				if (Singleton<全局变量类>.I.角色列表[i].是否在线)
				{
					在线发货_角色列表.Items.Add(Singleton<全局变量类>.I.角色列表[i].昵称);
				}
			}
			return;
		}
		在线发货_角色列表.Items.Clear();
		List<角色汇总类> list = Singleton<全局变量类>.I.角色列表.FindAll((角色汇总类 x) => x.是否在线 && x.昵称.Contains(在线发货_角色列表.Text, StringComparison.CurrentCulture));
		if (list != null)
		{
			for (int num = 0; num < list.Count; num++)
			{
				在线发货_角色列表.Items.Add(list[num].昵称);
