	private void 在线发货_确定发送按钮_Click(object sender, EventArgs e)
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		在线发货_发送提示.Text = string.Empty;
		if (string.IsNullOrWhiteSpace(在线发货_角色列表.Text))
		{
			MessageBox.Show("请选择在线的角色进行发送！");
			return;
		}
		if (在线发货_角色列表.Text == "所有在线玩家")
		{
			if (Singleton<全局变量类>.I.角色列表.Count <= 0)
			{
				MessageBox.Show("当前并无在线角色，无法发送！");
				return;
			}
		}
		else if (!Singleton<全局变量类>.I.角色列表.Any((角色汇总类 x) => x.昵称 == 在线发货_角色列表.Text))
		{
			MessageBox.Show("当前选择角色无效！");
			return;
		}
		if (!Enum.TryParse<AllEnums.数值Type>(在线发货_发送类型.Text, out var result))
		{
			MessageBox.Show("选择类型有误！");
			return;
		}
		if (在线发货_发送数量.Value == 0m)
		{
			在线发货_发送数量.Value = 1m;
		}
		if (result == AllEnums.数值Type.道具 && string.IsNullOrWhiteSpace(在线发货_发送名字.Text))
		{
			MessageBox.Show("请选择要发送的道具！");
			return;
		}
		if (result == AllEnums.数值Type.宠物 && string.IsNullOrWhiteSpace(在线发货_发送名字.Text))
		{
			MessageBox.Show("请选择要发送的宠物名字！");
			return;
		}
		if (result == AllEnums.数值Type.坐骑 && string.IsNullOrWhiteSpace(在线发货_发送名字.Text))
		{
			MessageBox.Show("请选择要发送的坐骑名字！");
			return;
		}
		Singleton<全局变量类>.I.验证client.SendRT(10028, 在线发货_角色列表.Text, (int)result, (int)在线发货_发送数量.Value, 在线发货_发送名字.Text);
	}

