	private void cdk删除事件回调(object sender, EventArgs e)
	{
		if (!base.IsHandleCreated || cdk兑换_cdk列表.CurrentRow == null)
		{
			return;
		}
		int index = cdk兑换_cdk列表.CurrentRow.Index;
		if (index >= 0)
		{
			DataGridViewCellCollection cells = cdk兑换_cdk列表.Rows[index].Cells;
			string 当前key = cells[0].Value.ToString();
			cdk兑换_cdk列表.Rows.RemoveAt(index);
			int num = Singleton<全局变量类>.I.CDK列表.FindIndex((CDK信息类 x) => x.卡密 == 当前key);
			if (num >= 0)
			{
				Singleton<全局变量类>.I.CDK列表.RemoveAt(num);
			}
			Singleton<全局变量类>.I.验证client.SendRT(10027, 当前key);
			NDebug.Log("操作：CDK删除  卡密：" + 当前key);
			CDK查询结果提示.Text = $"当前CDK总数量：{Singleton<全局变量类>.I.CDK列表.Count}";
		}
	}

