		string 卡密 = cdk兑换_查询卡密.Text;
		string 使用角色 = cdk兑换_查询使用者.Text;
		int cdk类型 = 0;
		if (string.IsNullOrWhiteSpace(cdk兑换_查询类型.Text))
		{
			cdk类型 = 0;
		}
		else if (cdk兑换_查询类型.Text == "道具")
		{
			cdk类型 = 1;
		}
		else if (cdk兑换_查询类型.Text == "点卡")
		{
			cdk类型 = 2;
		}
		else if (cdk兑换_查询类型.Text == "奇宝点")
		{
			cdk类型 = 17;
		}
		else if (cdk兑换_查询类型.Text == "注册码")
		{
			cdk类型 = 4;
		}
		List<CDK信息类> cdk列表 = Singleton<全局变量类>.I.CDK列表.FindAll((CDK信息类 x) => (x.卡密 == 卡密 || string.IsNullOrWhiteSpace(卡密)) && (x.CDK使用角色 == 使用角色 || string.IsNullOrWhiteSpace(使用角色)) && (x.CDK类型 == (AllEnums.CdkType)cdk类型 || cdk类型 == 0));
		cdk兑换_cdk列表.Invoke((MethodInvoker)delegate
		{
			cdk兑换_cdk列表.Rows.Clear();
			for (int i = 0; i < cdk列表.Count; i++)
			{
				cdk兑换_cdk列表.Rows.Add(cdk列表[i].卡密, cdk列表[i].CDK类型, cdk列表[i].CDK数量, cdk列表[i].CDK道具名字, cdk列表[i].CDK使用时间, cdk列表[i].CDK使用角色);
			}
			CDK查询结果提示.Text = $"当前查询结果：{cdk列表.Count}";
		});
	}

