	[Rpc(hash = 10066)]
	private void 返回CDK刷新(string cdk列表, bool 是否成功)
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		cdk兑换_cdk列表.Invoke((MethodInvoker)delegate
		{
			if (是否成功)
			{
				CDK信息类 cDK信息类 = JsonConvert.DeserializeObject<CDK信息类>(cdk列表);
				cdk兑换_cdk列表.Rows.Add(cDK信息类.卡密, cDK信息类.CDK类型, cDK信息类.CDK数量, cDK信息类.CDK道具名字, cDK信息类.CDK使用时间, cDK信息类.CDK使用角色);
				Singleton<全局变量类>.I.CDK列表.Add(cDK信息类);
			}
			CDK查询结果提示.Text = $"当前CDK总数量：{Singleton<全局变量类>.I.CDK列表.Count}";
		});
	}

	private static string 读文件(string filePath)
	{
		try
		{
			using FileStream stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
			using StreamReader streamReader = new StreamReader(stream, Encoding.UTF8);
			return streamReader.ReadToEnd();
		}
		catch (IOException ex)
		{
			NDebug.LogError("读文件-失败: " + ex.Message);
			return string.Empty;
		}
	}

	public static bool 写文件(string filePath, string content)
	{
		try
		{
			using (FileStream stream = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileShare.ReadWrite))
			{
				using StreamWriter streamWriter = new StreamWriter(stream, Encoding.UTF8);
				streamWriter.Write(content);
			}
			return true;
		}
		catch (IOException ex)
		{
			NDebug.LogError("写文件-失败: " + ex.Message);
			return false;
		}
	}

	public void CDK生成文本()
	{
		try
		{
			if (!base.IsHandleCreated)
			{
				return;
			}
			string text = string.Empty;
			string text2 = Environment.CurrentDirectory + "\\CDK生成文本.txt";
			if (!File.Exists(text2))
			{
				using (File.Create(text2))
				{
				}
			}
			else
			{
				text = 读文件(text2);
			}
			写文件(text2, text + "\n" + cdk兑换_生成cdk列表.Text);
			NDebug.LogWarning("CDK生成完毕，并且已经保存成功！");
		}
		catch (Exception ex)
		{
			NDebug.LogError("CDK生成文本-失败: " + ex.Message);
		}
		cdk兑换_生成cdk按钮.Invoke((MethodInvoker)delegate
		{
			cdk兑换_生成cdk按钮.Enabled = true;
		});
	}

