	[Rpc(hash = 10056)]
	public void 返回启动网关(bool 是否启动操作, int 启动状态)
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		if (是否启动操作)
		{
			switch (启动状态)
			{
			case 0:
				网关_启动状态.Text = "未启动";
				break;
			case 1:
				网关_启动状态.Text = "已启动";
				break;
			case 2:
				网关_启动状态.Text = "已启动";
				break;
			}
		}
		else
		{
			switch (启动状态)
			{
			case 0:
				网关_启动状态.Text = "未启动";
				break;
			case 1:
				网关_启动状态.Text = "关闭失败";
				break;
			case 2:
				网关_启动状态.Text = "已启动";
				break;
			}
		}
	}

	private void 个人发送事件处理(object sender, EventArgs e)
	{
		try
		{
			if (!base.IsHandleCreated || !Enum.TryParse<AllEnums.菜单操作类型>(((ToolStripMenuItem)sender).Tag.ToString(), out var result) || 角色监控_角色列表.CurrentRow == null)
			{
				return;
			}
			int index = 角色监控_角色列表.CurrentRow.Index;
			if (index < 0 && result < AllEnums.菜单操作类型.全区_清空全区存档)
			{
				MessageBox.Show("请选中要操作的角色！");
				return;
			}
			DataGridViewCellCollection 当前行 = null;
			角色汇总类 角色汇总类2 = null;
			if (index >= 0)
			{
				当前行 = 角色监控_角色列表.Rows[index].Cells;
