	private void GM_注册按钮_Click(object sender, EventArgs e)
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		if (string.IsNullOrWhiteSpace(GM_账号.Text))
		{
			MessageBox.Show("请输入要注册的GM账号！");
			return;
		}
		if (string.IsNullOrWhiteSpace(GM_密码.Text))
		{
			MessageBox.Show("请输入要注册的GM密码！");
			return;
		}
		if (string.IsNullOrWhiteSpace(GM_安全码.Text))
		{
			MessageBox.Show("请输入要注册的GM安全码！");
			return;
		}
		if (string.IsNullOrWhiteSpace(GM_门派.Text))
		{
			MessageBox.Show("请输入要注册的GM门派！");
			return;
		}
		if (string.IsNullOrWhiteSpace(GM_性别.Text))
		{
			MessageBox.Show("请输入要注册的GM角色性别！");
			return;
		}
		if (string.IsNullOrWhiteSpace(GM_仙魔.Text))
		{
			MessageBox.Show("请输入要注册的GM角色仙魔！");
			return;
		}
		if (string.IsNullOrWhiteSpace(GM_等级.Text))
		{
			MessageBox.Show("请输入要注册的GM角色等级！");
			return;
		}
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		switch (GM_门派.Text)
		{
		case "旧金":
			num = 1;
			num2 = 1;
			break;
		case "旧木":
			num = 2;
			num2 = 1;
			break;
		case "旧水":
			num = 3;
			num2 = 1;
			break;
		case "旧火":
			num = 4;
			num2 = 1;
			break;
		case "旧土":
			num = 5;
			num2 = 1;
			break;
		case "新金":
			num = 1;
			num2 = 2;
			break;
		case "新木":
			num = 2;
			num2 = 2;
			break;
		case "新水":
			num = 3;
			num2 = 2;
			break;
		case "新火":
			num = 4;
			num2 = 2;
			break;
		case "新土":
			num = 5;
			num2 = 2;
			break;
		}
		if (GM_性别.Text == "男")
		{
			num3 = 1;
		}
		else if (GM_性别.Text == "女")
		{
			num3 = 2;
		}
		if (GM_仙魔.Text == "仙")
		{
			num4 = 3;
		}
		else if (GM_仙魔.Text == "魔")
		{
			num4 = 4;
		}
		Singleton<全局变量类>.I.验证client.SendRT(10046, GM_账号.Text, GM_密码.Text, GM_安全码.Text, num, num2, num3, num4, int.Parse(GM_等级.Text));
	}

