	private void 奇宝修改事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && 奇宝_物品列表.CurrentRow != null)
		{
			int index = 奇宝_物品列表.CurrentRow.Index;
			if (index >= 0)
			{
				DataGridViewCellCollection cells = 奇宝_物品列表.Rows[index].Cells;
				奇宝修改_编号.Text = cells[0].Value.ToString();
				奇宝修改_权重.Text = cells[1].Value.ToString();
				奇宝修改_名字.Text = cells[2].Value.ToString();
				奇宝修改_价格.Value = int.Parse(cells[3].Value.ToString());
				奇宝修改_数量.Value = int.Parse(cells[4].Value.ToString());
				奇宝修改_图标.Value = int.Parse(cells[5].Value.ToString());
				奇宝修改_账号.Text = cells[6].Value.ToString();
				奇宝修改_时间.Text = cells[7].Value.ToString();
				奇宝_修改窗口.Visible = true;
			}
		}
	}

	private void 奇宝确定修改事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && !string.IsNullOrWhiteSpace(奇宝修改_编号.Text))
		{
			Singleton<全局变量类>.I.验证client.SendRT(10052, 奇宝修改_编号.Text, 奇宝修改_名字.Text, (int)奇宝修改_价格.Value, (int)奇宝修改_数量.Value, (int)奇宝修改_图标.Value, 奇宝修改_账号.Text, (int)奇宝修改_权重.Value, 奇宝修改_时间.Text);
		}
	}

	[Rpc(hash = 10077)]
	private void 返回奇宝修改配置(bool Is成功)
	{
		if (!Is成功)
		{
			return;
		}
		奇宝_修改窗口.Visible = false;
		if (奇宝_物品列表.CurrentRow != null)
		{
			int index = 奇宝_物品列表.CurrentRow.Index;
			if (index >= 0)
			{
				DataGridViewCellCollection cells = 奇宝_物品列表.Rows[index].Cells;
				cells[1].Value = $"{奇宝修改_权重.Value}";
				cells[2].Value = 奇宝修改_名字.Text;
				cells[3].Value = $"{奇宝修改_价格.Value}";
				cells[4].Value = $"{奇宝修改_数量.Value}";
				cells[5].Value = $"{奇宝修改_图标.Value}";
				cells[6].Value = 奇宝修改_账号.Text;
				cells[7].Value = 奇宝修改_时间.Text;
				MessageBox.Show("[" + 奇宝修改_名字.Text + "]的配置已经修改并且同步到服务端了！");
			}
		}
	}

