	private void 奇宝斋组件赋值()
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		奇宝_开关.Checked = Singleton<全局变量类>.I.奇宝斋配置.功能开关;
		奇宝_玩家开关.Checked = Singleton<全局变量类>.I.奇宝斋配置.玩家上架开关;
		奇宝_手续费.Value = Singleton<全局变量类>.I.奇宝斋配置.卖出手续费;
		奇宝_押金.Value = Singleton<全局变量类>.I.奇宝斋配置.上架押金;
		奇宝_比例.Value = Singleton<全局变量类>.I.奇宝斋配置.奇宝点比例;
		奇宝_充值网站.Text = Singleton<全局变量类>.I.奇宝斋配置.充值网址;
		奇宝_可上架物品.Text = Singleton<全局变量类>.I.奇宝斋配置.可上架商品;
		奇宝_物品列表.Invoke((MethodInvoker)delegate
		{
			奇宝_物品列表.Rows.Clear();
			foreach (奇宝斋数据类 value in Singleton<全局变量类>.I.奇宝斋配置.物品列表.Values)
			{
				奇宝_物品列表.Rows.Add(value.物品编号, value.物品权重, value.物品名称, value.物品价格, value.出售数量, value.物品图标, value.出售账号, value.到期时间);
			}
		});
	}

