	[Rpc(hash = 10075)]
	private void 返回奇宝上架配置(string 新增商品json)
	{
		if (string.IsNullOrWhiteSpace(新增商品json))
		{
			MessageBox.Show("新增商品失败！");
			return;
		}
		NDebug.Log("奇宝斋商品新增成功！");
		奇宝斋数据类 新增商品 = JsonConvert.DeserializeObject<奇宝斋数据类>(新增商品json);
		Singleton<全局变量类>.I.奇宝斋配置.物品列表.TryAdd(新增商品.物品编号, 新增商品);
		奇宝_物品列表.Invoke((MethodInvoker)delegate
		{
			奇宝_物品列表.Rows.Add(新增商品.物品编号, 新增商品.物品权重, 新增商品.物品名称, 新增商品.物品价格, 新增商品.出售数量, 新增商品.物品图标, 新增商品.出售账号, 新增商品.到期时间);
