	private void 登录_确定_Click(object sender, EventArgs e)
	{
		ushort result;
		if (string.IsNullOrWhiteSpace(登录_IP.Text))
		{
			MessageBox.Show("请输入IP！");
		}
		else if (string.IsNullOrWhiteSpace(登录_端口.Text))
		{
			MessageBox.Show("请输入端口！");
		}
		else if (!ushort.TryParse(登录_端口.Text, out result))
		{
			MessageBox.Show("请输入正确的端口！");
		}
		else if (string.IsNullOrWhiteSpace(登录_账号.Text))
		{
			MessageBox.Show("请输入管理员账号！");
		}
		else if (string.IsNullOrWhiteSpace(登录_卡密.Text))
		{
			MessageBox.Show("请输入授权卡密！");
		}
		else if (string.IsNullOrWhiteSpace(登录_密码.Text))
		{
			MessageBox.Show("请输入管理员密码！");
		}
		else
		{
			连接校验();
		}
	}

	private async Task 连接校验()
	{
		if (!Singleton<全局变量类>.I.验证client.Connected)
		{
			await Singleton<全局变量类>.I.验证client.Connect(登录_IP.Text, ushort.Parse(登录_端口.Text));
			await Task.Delay(1000);
			if (!Singleton<全局变量类>.I.验证client.Connected)
			{
				MessageBox.Show("顺风插件后台连接失败，请检查IP端口是否正确！");
				return;
			}
			Singleton<全局变量类>.I.验证client.SendRT(10014, false);
			await Task.Delay(100);
		}
		Singleton<全局变量类>.I.验证client.SendRT(10015, 登录_卡密.Text, 登录_账号.Text, 登录_密码.Text);
	}

	[Rpc(hash = 10057)]
	public async void 返回后台登录(bool Is成功, string 提示文本)
	{
		if (!Is成功)
		{
			设置窗口状态事件(是否成功: false);
			MessageBox.Show(提示文本);
			return;
		}
		Singleton<全局变量类>.I.config.IP = 登录_IP.Text;
		ushort.TryParse(登录_端口.Text, out var result);
		Singleton<全局变量类>.I.config.Port = result;
		Singleton<全局变量类>.I.config.Admin = 登录_账号.Text;
		Singleton<全局变量类>.I.config.PassWord = 登录_密码.Text;
		Singleton<全局变量类>.I.config.License = 登录_卡密.Text;
		Singleton<全局变量类>.I.Config保存();
		设置窗口状态事件(是否成功: true);
		await Task.Delay(1000);
		初始化();
	}

	public void 设置窗口状态事件(bool 是否成功)
	{
		if (base.IsHandleCreated)
		{
			首页小界面.Visible = !是否成功;
			if (!是否成功)
			{
				base.Size = new Size
				{
					Width = 小界面[0],
					Height = 小界面[1]
				};
			}
			else
			{
				base.Size = new Size
				{
					Width = 大界面[0],
					Height = 大界面[1]
				};
			}
		}
	}

