	{
		try
		{
			if (!Is成功)
			{
				MessageBox.Show(配置内容);
				return;
			}
			if (配置类型 == TimedDungeonConfigType)
			{
				限时副本地图配置窗口.I.加载远程配置(配置内容);
				NDebug.Log("操作：请求/重载[限时副本地图配置]");
				return;
			}
			switch ((AllEnums.后台通信类型)配置类型)
			{
			case AllEnums.后台通信类型.后台首页配置:
