	private void 发包按钮_Click(object sender, EventArgs e)
	{
		if (string.IsNullOrWhiteSpace(发包文本.Text))
		{
			MessageBox.Show("发包文本为空！");
		}
		else
		{
			链接发包服务器();
		}
	}

	private async Task 链接发包服务器()
	{
		Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
		await socket.ConnectAsync(new IPEndPoint(IPAddress.Parse(发包ip.Text), int.Parse(发包端口.Text)));
		NDebug.Log("连接服务器成功");
		string[] 临时缓存 = 发包文本.Lines;
		发包文本.Text = string.Empty;
		for (int i = 0; i < 临时缓存.Length; i++)
		{
			if (!string.IsNullOrWhiteSpace(临时缓存[i]))
			{
				if (发包文本.Lines.Length > 100)
				{
					发包文本.Text = string.Empty;
				}
				socket.Send(临时缓存[i].Split(',').Select(byte.Parse).ToArray());
				await Task.Delay(10);
				发包文本.Text += (socket.Connected ? $"{DateTime.Now:yyyy-MM-dd HH:mm:ss}[成功]{临时缓存[i]}\r\n" : $"{DateTime.Now:yyyy-MM-dd HH:mm:ss}[失败]{临时缓存[i]}\r\n");
			}
		}
		MessageBox.Show("发送完毕！");
	}

