	private void 融丹_添加按钮_Click(object sender, EventArgs e)
	{
		if (string.IsNullOrWhiteSpace(融丹_添加类型.Text))
		{
			MessageBox.Show("请选择添加的奖励类型！");
			return;
		}
		if (string.IsNullOrWhiteSpace(融丹_添加名字.Text))
		{
			MessageBox.Show("请填写要添加的[" + 融丹_添加类型.Text + "]名字！");
			return;
		}
		if (string.IsNullOrWhiteSpace(融丹_添加品级.Text))
		{
			MessageBox.Show("请选择添加的奖励品级！");
			return;
		}
		if (融丹_添加数量1.Value > 融丹_添加数量2.Value || (融丹_添加数量1.Value == 0m && 融丹_添加数量2.Value == 0m))
		{
			MessageBox.Show("请添加正确的奖励数量区间！");
			return;
		}
		融丹奖池类 addDate = new 融丹奖池类
		{
			类型 = Enum.Parse<AllEnums.数值Type>(融丹_添加类型.Text),
			名字 = 融丹_添加名字.Text,
			等级 = Enum.Parse<AllEnums.荣丹Type>(融丹_添加品级.Text),
			数量区间 = new int[2]
			{
				(int)融丹_添加数量1.Value,
				(int)融丹_添加数量2.Value
			},
			概率 = (int)融丹_添加概率.Value,
			价值 = (int)融丹_添加价值.Value
		};
		Singleton<全局变量类>.I.融丹配置.奖池.Add(addDate);
		融丹_奖池列表.Invoke((MethodInvoker)delegate
		{
			融丹_奖池列表.Rows.Add(addDate.类型, addDate.名字, addDate.等级, (addDate.数量区间.Length == 2) ? $"{addDate.数量区间[0]}-{addDate.数量区间[1]}" : "0", $"{addDate.概率}/10000", addDate.价值, Singleton<全局变量类>.I.融丹配置.奖池.Count - 1);
		});
		NDebug.Log("融丹奖励添加成功！");
	}

	private void 融丹_添加类型_SelectedIndexChanged(object sender, EventArgs e)
	{
		if (融丹_添加类型.Text == "道具" || 融丹_添加类型.Text == "宠物" || 融丹_添加类型.Text == "坐骑")
		{
			融丹_添加名字.Text = string.Empty;
		}
		else
		{
			融丹_添加名字.Text = 融丹_添加类型.Text;
		}
	}

	private void 融丹修改事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && 融丹_奖池列表.CurrentRow != null)
		{
			int result = 融丹_奖池列表.CurrentRow.Index;
			if (result >= 0 && result < Singleton<全局变量类>.I.融丹配置.奖池.Count)
			{
				int.TryParse(融丹_奖池列表.Rows[result].Cells[6].Value.ToString(), out result);
				融丹奖池类 融丹奖池类2 = Singleton<全局变量类>.I.融丹配置.奖池[result];
				融丹修改_类型.Tag = result.ToString();
				融丹修改_类型.Text = 融丹奖池类2.类型.ToString();
				融丹修改_名字.Text = 融丹奖池类2.名字;
				融丹修改_品级.Text = 融丹奖池类2.等级.ToString();
				融丹修改_数量1.Value = 融丹奖池类2.数量区间[0];
				融丹修改_数量2.Value = 融丹奖池类2.数量区间[1];
				融丹修改_概率.Value = 融丹奖池类2.概率;
				融丹修改_价值.Value = 融丹奖池类2.价值;
				融丹_修改窗口.Visible = true;
				融丹_奖池列表.Enabled = false;
			}
		}
	}

	private void 融丹确定修改事件回调(object sender, EventArgs e)
	{
		if (!base.IsHandleCreated || string.IsNullOrWhiteSpace(融丹修改_类型.Tag.ToString()))
		{
			return;
		}
		int.TryParse(融丹修改_类型.Tag.ToString(), out var result);
		if (result >= 0 && result < Singleton<全局变量类>.I.融丹配置.奖池.Count)
		{
			融丹奖池类 融丹奖池类2 = Singleton<全局变量类>.I.融丹配置.奖池[result];
			融丹奖池类2.名字 = 融丹修改_名字.Text;
			Enum.TryParse<AllEnums.荣丹Type>(融丹修改_品级.Text, out 融丹奖池类2.等级);
			融丹奖池类2.数量区间[0] = (int)融丹修改_数量1.Value;
			融丹奖池类2.数量区间[1] = (int)融丹修改_数量2.Value;
			融丹奖池类2.概率 = (int)融丹修改_概率.Value;
			融丹奖池类2.价值 = (int)融丹修改_价值.Value;
			融丹修改_类型.Tag = string.Empty;
			融丹_修改窗口.Visible = false;
			融丹_奖池列表.Enabled = true;
			result = 融丹_奖池列表.CurrentRow.Index;
			if (result >= 0)
			{
				DataGridViewCellCollection cells = 融丹_奖池列表.Rows[result].Cells;
				cells[1].Value = 融丹奖池类2.名字;
				cells[2].Value = 融丹奖池类2.等级;
				cells[3].Value = $"{融丹奖池类2.数量区间[0]}-{融丹奖池类2.数量区间[1]}";
				cells[4].Value = $"{融丹奖池类2.概率}/10000";
				cells[5].Value = 融丹奖池类2.价值;
				MessageBox.Show("修改成功！");
			}
		}
	}

	private void 融丹删除事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && 融丹_奖池列表.CurrentRow != null)
		{
			int index = 融丹_奖池列表.CurrentRow.Index;
			if (index >= 0 && index < Singleton<全局变量类>.I.融丹配置.奖池.Count && int.TryParse(融丹_奖池列表.Rows[index].Cells[6].Value.ToString(), out var result))
			{
				融丹_奖池列表.Rows.RemoveAt(index);
				Singleton<全局变量类>.I.融丹配置.奖池.RemoveAt(result);
			}
		}
	}

