	private void 宠物转生_转生次数_ValueChanged(object sender, EventArgs e)
	{
		int count = 宠物转生_列表.Rows.Count;
		if (宠物转生_转生次数.Value > (decimal)count)
		{
			for (int i = count; (decimal)i < 宠物转生_转生次数.Value; i++)
			{
				宠物转生_列表.Rows.Add(i + 1, 1, 0, string.Empty, 1, true, 1, true, 0, 0, string.Empty, string.Empty, 0, 330, 0);
			}
		}
		else if (宠物转生_转生次数.Value < (decimal)count)
		{
			int num = count;
			while ((decimal)num > 宠物转生_转生次数.Value)
			{
				宠物转生_列表.Rows.RemoveAt(num - 1);
				num--;
			}
		}
	}

