	private void 掉落扩展_add_添加按钮_Click(object sender, EventArgs e)
	{
		if (string.IsNullOrWhiteSpace(掉落扩展_选择_类型.Text) || string.IsNullOrWhiteSpace(掉落扩展_add_类型.Text))
		{
			return;
		}
		if (掉落扩展_add_类型.Text == "道具" && string.IsNullOrWhiteSpace(掉落扩展_add_道具.Text))
		{
			MessageBox.Show("请选择要掉落的道具名字！");
			return;
		}
		if (掉落扩展_add_类型.Text != "道具")
		{
			掉落扩展_add_道具.Text = 掉落扩展_add_类型.Text;
		}
		if (掉落扩展_选择_类型.Text == "吞天")
		{
			掉落扩展_吞天_列表.Rows.Add(掉落扩展_add_类型.Text, 掉落扩展_add_道具.Text, 掉落扩展_add_最低数量.Value, 掉落扩展_add_最高数量.Value, 掉落扩展_add_几率.Value, 掉落扩展_add_首杀.Checked);
		}
		else if (掉落扩展_选择_类型.Text == "噬地")
		{
			掉落扩展_噬地_列表.Rows.Add(掉落扩展_add_类型.Text, 掉落扩展_add_道具.Text, 掉落扩展_add_最低数量.Value, 掉落扩展_add_最高数量.Value, 掉落扩展_add_几率.Value, 掉落扩展_add_首杀.Checked);
		}
		else if (掉落扩展_选择_类型.Text == "傀儡王")
		{
			掉落扩展_傀儡王_列表.Rows.Add(掉落扩展_add_类型.Text, 掉落扩展_add_道具.Text, 掉落扩展_add_最低数量.Value, 掉落扩展_add_最高数量.Value, 掉落扩展_add_几率.Value, 掉落扩展_add_首杀.Checked);
		}
		else if (掉落扩展_选择_类型.Text == "世界boss")
		{
			掉落扩展_世界_列表.Rows.Add(掉落扩展_add_类型.Text, 掉落扩展_add_道具.Text, 掉落扩展_add_最低数量.Value, 掉落扩展_add_最高数量.Value, 掉落扩展_add_几率.Value, 掉落扩展_add_首杀.Checked);
		}
		MessageBox.Show("[" + 掉落扩展_选择_类型.Text + "]掉落添加成功！");
	}

