	private string 道行下限字典提示处理()
	{
		if (string.IsNullOrWhiteSpace(地府_道行下限字典.Text))
		{
			return string.Empty;
		}
		string[] array = 地府_道行下限字典.Text.Split("/");
		if (array.Length == 0)
		{
			return string.Empty;
		}
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < array.Length; i++)
		{
			string[] array2 = array[i].Split("=");
			if (array2.Length == 2)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(12, 2, stringBuilder2);
				handler.AppendLiteral("等级：");
				handler.AppendFormatted(array2[0]);
				handler.AppendLiteral("（≥");
				handler.AppendFormatted(array2[1]);
				handler.AppendLiteral("年道行可购买）");
				stringBuilder2.AppendLine(ref handler);
			}
		}
		return stringBuilder.ToString();
	}

