	private void 神算删除事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && 神算_列表.CurrentRow != null)
		{
			int index = 神算_列表.CurrentRow.Index;
			if (index >= 0)
			{
				神算_列表.Rows.RemoveAt(index);
			}
		}
	}

	private void 神算置顶事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && 神算_列表.CurrentRow != null)
		{
			int index = 神算_列表.CurrentRow.Index;
			if (index >= 0)
			{
				DataGridViewRow dataGridViewRow = 神算_列表.Rows[index];
				神算_列表.Rows.RemoveAt(index);
				神算_列表.Rows.Insert(0, dataGridViewRow);
				神算_列表.CurrentCell = 神算_列表.Rows[0].Cells[0];
			}
		}
	}

	private void 神算下移事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && 神算_列表.CurrentRow != null)
		{
			int index = 神算_列表.CurrentRow.Index;
			if (index >= 0 && index + 1 < 神算_列表.Rows.Count)
			{
				DataGridViewRow dataGridViewRow = 神算_列表.Rows[index];
				int num = index + 1;
				神算_列表.Rows.RemoveAt(index);
				神算_列表.Rows.Insert(num, dataGridViewRow);
				神算_列表.CurrentCell = 神算_列表.Rows[num].Cells[0];
			}
		}
	}

	private void 神算上移事件回调(object sender, EventArgs e)
	{
		if (base.IsHandleCreated && 神算_列表.CurrentRow != null)
		{
			int index = 神算_列表.CurrentRow.Index;
			if (index > 0)
			{
				DataGridViewRow dataGridViewRow = 神算_列表.Rows[index];
				int num = index - 1;
				神算_列表.Rows.RemoveAt(index);
				神算_列表.Rows.Insert(num, dataGridViewRow);
				神算_列表.CurrentCell = 神算_列表.Rows[num].Cells[0];
			}
		}
	}

	private void 合区_连接按钮_Click(object sender, EventArgs e)
	{
		if (string.IsNullOrWhiteSpace(合区_ip.Text) || string.IsNullOrWhiteSpace(合区_密码.Text) || string.IsNullOrWhiteSpace(合区_端口.Text) || string.IsNullOrWhiteSpace(合区_账号.Text) || string.IsNullOrWhiteSpace(合区_表1.Text) || string.IsNullOrWhiteSpace(合区_表2.Text))
		{
			MessageBox.Show("数据库信息填写不完整。");
			return;
		}
		Singleton<全局变量类>.I.验证client.SendRT(10083, 1, 合区_ip.Text, 合区_密码.Text, 合区_端口.Text, 合区_账号.Text, 合区_表1.Text, 合区_表2.Text);
	}

	private void 合区_读取按钮_Click(object sender, EventArgs e)
	{
		Singleton<全局变量类>.I.验证client.SendRT(10083, 2, 合区_ip.Text, 合区_密码.Text, 合区_端口.Text, 合区_账号.Text, 合区_表1.Text, 合区_表2.Text);
	}

	private void 合区_合批按钮_Click(object sender, EventArgs e)
	{
		合区_日志.Text = string.Empty;
		合区_合批按钮.Enabled = false;
		Singleton<全局变量类>.I.验证client.SendRT(10083, 3, 合区_ip.Text, 合区_密码.Text, 合区_端口.Text, 合区_账号.Text, 合区_表1.Text, 合区_表2.Text);
	}

	[Rpc(hash = 10083)]
	private void 合区返回数据(int 类型, bool 正常状态, string 文本)
	{
		switch (类型)
		{
		case 1:
			合区_连接按钮.Enabled = !正常状态;
			MessageBox.Show(文本);
			break;
		case 2:
			MessageBox.Show(文本);
			break;
		case 3:
		{
			if (正常状态)
			{
				合区_连接按钮.Enabled = true;
				合区_合批按钮.Enabled = true;
			}
			TextBox textBox = 合区_日志;
			textBox.Text = textBox.Text + 文本 + "\n\r";
			break;
		}
		}
	}

