	[Rpc(hash = 10084)]
	private void 请求适配操作(bool 状态, string 提示信息)
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		Invoke((MethodInvoker)delegate
		{
			try
			{
				if (!状态)
				{
					MessageBox.Show(提示信息);
				}
				else
				{
					string baseDirectory = AppDomain.CurrentDomain.BaseDirectory;
					foreach (string value in 全局变量类.O文件路径列表.Values)
					{
						bool flag;
						switch (value)
						{
						case "lib_gs32.pak\\gs\\daemons\\actions\\double_magic_hit.o":
						case "lib_gs32.pak\\gs\\daemons\\actions\\magic_double_hit.o":
						case "lib_gs32.pak\\gs\\daemons\\actions\\multi_physical_attack.o":
							flag = true;
							break;
						default:
							flag = false;
							break;
						}
						if (!flag && !File.Exists(Path.Combine(baseDirectory, value)))
						{
							MessageBox.Show("请把后台放在正确的路径下使用", "错误", MessageBoxButtons.OK, MessageBoxIcon.Hand);
							return;
						}
					}
					foreach (KeyValuePair<string, string> item in 全局变量类.O文件路径列表)
					{
						string path = Path.Combine(baseDirectory, item.Value);
						byte[] array = 取嵌入式资源(item.Key);
						if (array != null)
						{
							if (item.Key == "NetClientFrom.Resources.logind.o")
							{
								array = Singleton<ByteAPI>.I.寻找字节集并替换(array, new byte[18]
								{
									49, 50, 51, 52, 53, 54, 55, 56, 46, 103,
									121, 121, 120, 46, 99, 110, 35, 116
								}, Encoding.ASCII.GetBytes(Singleton<ByteAPI>.I.取文本左边(Singleton<全局变量类>.I.首页配置.卡密, 18)));
							}
							File.WriteAllBytes(path, array);
						}
					}
					MessageBox.Show("✅适配成功，已完成。");
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show("出现错误：" + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			}
		});
	}

	private byte[] 取嵌入式资源(string 资源完整路径)
	{
		Stream manifestResourceStream = Assembly.GetExecutingAssembly().GetManifestResourceStream(资源完整路径);
		if (manifestResourceStream != null)
		{
			using (manifestResourceStream)
			{
				byte[] array = new byte[manifestResourceStream.Length];
				manifestResourceStream.Read(array, 0, array.Length);
				return array;
			}
		}
		return null;
	}

