	private void 元神系统配置组件赋值()
	{
		if (!base.IsHandleCreated)
		{
			return;
		}
		元神系统配置_功能开关.Checked = Singleton<全局变量类>.I.元神系统配置.功能开关;
		元神系统配置_禁止灵气存储.Checked = Singleton<全局变量类>.I.元神系统配置.禁止灵气存储;
		元神系统配置_初始赠送礼包.Text = Singleton<全局变量类>.I.元神系统配置.初始赠送礼包;
		元神系统配置_当前境界上限.Text = Singleton<全局变量类>.I.元神系统配置.当前境界上限.ToString();
		元神系统配置_超过BOSS二层境界不获得任何奖励.Checked = Singleton<全局变量类>.I.元神系统配置.超过BOSS二层境界不获得任何奖励;
		元神系统配置_开启破境BOSS同境界挑战限制.Checked = Singleton<全局变量类>.I.元神系统配置.开启破境BOSS同境界挑战限制;
		元神系统配置_限制使用特技地图.Text = Singleton<全局变量类>.I.元神系统配置.限制使用特技地图;
		元神系统配置_限制使用特技名字.Text = Singleton<全局变量类>.I.元神系统配置.限制使用特技名字;
		元神系统配置_渡劫地图.Text = Singleton<全局变量类>.I.元神系统配置.渡劫地图;
		元神系统配置_地图坐标X.Text = Singleton<全局变量类>.I.元神系统配置.地图坐标X;
		元神系统配置_地图坐标Y.Text = Singleton<全局变量类>.I.元神系统配置.地图坐标Y;
		装备进阶配置_转化道具.Text = Singleton<全局变量类>.I.元神系统配置.转化道具;
		装备进阶配置_功能开关.Checked = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.功能开关;
		装备进阶配置_Is等级要求.Checked = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.Is等级要求;
		装备进阶配置_最低等级.Text = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.最低等级.ToString();
		装备进阶配置_Is道行要求.Checked = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.Is道行要求;
		装备进阶配置_最低道行.Text = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.最低道行.ToString();
		装备进阶配置_Is装备等级要求.Checked = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.Is装备等级要求;
		装备进阶配置_最低装备等级.Text = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.最低装备等级.ToString();
		装备进阶配置_Is改造要求.Checked = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.Is改造要求;
		装备进阶配置_最低改造.Text = Singleton<全局变量类>.I.元神系统配置.装备升阶数据.最低改造.ToString();
		装备进阶配置_需求字典.Rows.Clear();
		装备进阶配置_需求字典.Invoke((MethodInvoker)delegate
		{
			for (int i = 1; i <= 10; i++)
			{
				if (Singleton<全局变量类>.I.元神系统配置.装备升阶数据.需求字典.TryGetValue((AllEnums.元神境界)i, out 升阶需求类 value))
				{
					装备进阶配置_需求字典.Rows.Add($"{(AllEnums.元神境界)i}", value.需求材料, value.需求数量, value.浮动率);
				}
			}
		});
		装备进阶配置_属性字典.Rows.Clear();
