			for (int i = 0; i < 装备进阶配置_需求字典.Rows.Count; i++)
			{
				DataGridViewCellCollection cells = 装备进阶配置_需求字典.Rows[i].Cells;
				if (cells[0].Value != null && !string.IsNullOrWhiteSpace(cells[0].Value.ToString()) && Enum.TryParse<AllEnums.元神境界>(Convert.ToString(cells[0].Value), out var result) && Singleton<全局变量类>.I.元神系统配置.装备升阶数据.需求字典.ContainsKey(result))
				{
					Singleton<全局变量类>.I.元神系统配置.装备升阶数据.需求字典[result].需求材料 = Convert.ToString(cells[1].Value);
					Singleton<全局变量类>.I.元神系统配置.装备升阶数据.需求字典[result].需求数量 = Convert.ToInt32(cells[2].Value);
					Singleton<全局变量类>.I.元神系统配置.装备升阶数据.需求字典[result].浮动率 = Convert.ToInt32(cells[3].Value);
