			}
			Singleton<全局变量类>.I.元神系统配置.装备升阶数据.属性字典.Clear();
			for (int j = 0; j < 装备进阶配置_属性字典.Rows.Count; j++)
			{
				DataGridViewCellCollection cells2 = 装备进阶配置_属性字典.Rows[j].Cells;
				if (cells2[0].Value != null && !string.IsNullOrWhiteSpace(cells2[0].Value.ToString()) && Enum.TryParse<AllEnums.属性名字Type>(Convert.ToString(cells2[0].Value), out var result2))
				{
					int[] value = Convert.ToString(cells2[1].Value).Split(',').Select(int.Parse)
						.ToArray();
					Singleton<全局变量类>.I.元神系统配置.装备升阶数据.属性字典.TryAdd(result2, value);
				}
			}
			Singleton<全局变量类>.I.元神系统配置.本命法宝属性.Clear();
			Singleton<全局变量类>.I.元神系统配置.本命法宝属性.TryAdd(0, new 本命法宝属性类());
			for (int k = 0; k < 本命法宝配置_列表.Rows.Count; k++)
			{
				DataGridViewCellCollection cells3 = 本命法宝配置_列表.Rows[k].Cells;
				if (cells3[0].Value == null || string.IsNullOrWhiteSpace(cells3[0].Value.ToString()))
				{
					continue;
				}
				string[] array = Convert.ToString(cells3[3].Value).Split(',');
				List<通用属性类> list = new List<通用属性类>();
				for (int l = 0; l < array.Length; l++)
				{
					string[] array2 = array[l].Split('+');
					if (array2.Length == 2 && Enum.TryParse<AllEnums.属性名字Type>(array2[0], out var result3) && int.TryParse(array2[1], out var result4))
					{
						list.Add(new 通用属性类
						{
							属性名字 = result3,
							属性数值 = result4
						});
					}
				}
				本命法宝属性类 value2 = new 本命法宝属性类
				{
					强化道具 = Convert.ToString(cells3[1].Value),
					强化进度 = Convert.ToInt32(cells3[2].Value),
					属性列表 = list
				};
				Singleton<全局变量类>.I.元神系统配置.本命法宝属性.TryAdd(Convert.ToInt32(cells3[0].Value), value2);
			}
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.功能开关 = 心法配置_功能开关.Checked;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.Is等级要求 = 心法配置_Is等级要求.Checked;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.最低等级 = Convert.ToInt32(心法配置_最低等级.Text);
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.Is武学要求 = 心法配置_Is武学要求.Checked;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.最低武学 = Convert.ToInt32(心法配置_最低武学.Text);
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.心法最低等级要求 = Convert.ToInt32(心法配置_心法最低等级要求.Text);
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.心法最高升级等级 = Convert.ToInt32(心法配置_心法最高升级等级.Text);
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.气血升级道具 = 心法配置_气血升级道具.Text;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.速度升级道具 = 心法配置_速度升级道具.Text;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.攻击升级道具 = 心法配置_攻击升级道具.Text;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.防御升级道具 = 心法配置_防御升级道具.Text;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.随机升级道具 = 心法配置_随机升级道具.Text;
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.最低消耗数量 = Convert.ToInt32(心法配置_最低消耗数量.Text);
			Singleton<全局变量类>.I.元神系统配置.心法升级配置.递增消耗倍数 = Convert.ToInt32(心法配置_递增消耗倍数.Text);
			Singleton<全局变量类>.I.元神系统配置.灵幡附灵配置.功能开关 = 灵幡附灵_功能开关.Checked;
			Singleton<全局变量类>.I.元神系统配置.灵幡附灵配置.一阶灵幡名字 = 灵幡附灵_一阶灵幡名字.Text;
			Singleton<全局变量类>.I.元神系统配置.灵幡附灵配置.二阶灵幡名字 = 灵幡附灵_二阶灵幡名字.Text;
			Singleton<全局变量类>.I.元神系统配置.灵幡附灵配置.三阶灵幡名字 = 灵幡附灵_三阶灵幡名字.Text;
			Singleton<全局变量类>.I.元神系统配置.灵幡附灵配置.四阶灵幡名字 = 灵幡附灵_四阶灵幡名字.Text;
			Singleton<全局变量类>.I.元神系统配置.灵幡附灵配置.附灵字典.Clear();
			for (int m = 0; m < 灵幡附灵_附灵字典.Rows.Count; m++)
			{
				DataGridViewCellCollection cells4 = 灵幡附灵_附灵字典.Rows[m].Cells;
				if (cells4[0].Value == null || string.IsNullOrWhiteSpace(cells4[0].Value.ToString()) || !(cells4[0] is DataGridViewTextBoxCell { MaxInputLength: var maxInputLength }))
				{
					continue;
				}
				string[] array3 = Convert.ToString(cells4[3].Value).Split(',');
				List<通用属性类> list2 = new List<通用属性类>();
				for (int n = 0; n < array3.Length; n++)
				{
					string[] array4 = array3[n].Split('+');
					if (array4.Length == 2 && Enum.TryParse<AllEnums.属性名字Type>(array4[0], out var result5) && int.TryParse(array4[1], out var result6))
					{
						list2.Add(new 通用属性类
						{
							属性名字 = result5,
							属性数值 = result6
						});
					}
				}
				Singleton<全局变量类>.I.元神系统配置.灵幡附灵配置.附灵字典.TryAdd(maxInputLength, new 引灵幡属性列表类
				{
					附灵道具 = Convert.ToString(cells4[1].Value),
					需求数量 = Convert.ToInt32(cells4[2].Value),
					属性列表 = list2
				});
			}
			// Commit the active cell before reading it; never rebuild this grid from the old dictionary during save.
			if (元神_战斗背景列表.IsCurrentCellDirty)
			{
				元神_战斗背景列表.CommitEdit(DataGridViewDataErrorContexts.Commit);
			}
			元神_战斗背景列表.EndEdit();
			Dictionary<AllEnums.元神境界, int> battleBackgrounds = new Dictionary<AllEnums.元神境界, int>();
			for (int num = 0; num < 元神_战斗背景列表.Rows.Count; num++)
			{
				DataGridViewCellCollection cells5 = 元神_战斗背景列表.Rows[num].Cells;
				if (cells5[0].Value != null && !string.IsNullOrWhiteSpace(cells5[0].Value.ToString()) && Enum.TryParse<AllEnums.元神境界>(Convert.ToString(cells5[0].Value), out var result7))
				{
					if (int.TryParse(Convert.ToString(cells5[1].Value), out int backgroundId) && backgroundId >= 0)
					{
						battleBackgrounds[result7] = backgroundId;
					}
					else
					{
						throw new FormatException($"元神战斗背景编号无效：{cells5[1].Value}");
					}
				}
			}
			Singleton<全局变量类>.I.元神系统配置.战斗背景列表.Clear();
			foreach (KeyValuePair<AllEnums.元神境界, int> battleBackground in battleBackgrounds)
			{
				Singleton<全局变量类>.I.元神系统配置.战斗背景列表[battleBackground.Key] = battleBackground.Value;
			}
			return true;
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message, "元神系统配置保存失败", MessageBoxButtons.OK, MessageBoxIcon.Error);
			return false;
		}
	}

	private void 元神系统配置保存按钮_Click(object sender, EventArgs e)
	{
		if (元神系统配置组件存档())
		{
			Singleton<全局变量类>.I.验证client.SendRT(10018, 70, JsonConvert.SerializeObject(Singleton<全局变量类>.I.元神系统配置, Formatting.Indented));
		}
	}

	private void 元神系统配置重载按钮_Click(object sender, EventArgs e)
	{
		Singleton<全局变量类>.I.验证client.SendRT(10017, 70);
	}

	private async void 元神系统配置_清除首破存档_Click(object sender, EventArgs e)
	{
		if (MessageBox.Show("确定要清除记录的全服首次突破境界的道友存档吗？", "提示", MessageBoxButtons.OKCancel, MessageBoxIcon.Question) == DialogResult.OK)
		{
			Singleton<全局变量类>.I.验证client.SendRT(10017, 37);
			await Task.Delay(1000);
			Singleton<全局变量类>.I.全服共享存档数据.全服境界突破第一人组.Clear();
			Singleton<全局变量类>.I.验证client.SendRT(10088, JsonConvert.SerializeObject(Singleton<全局变量类>.I.全服共享存档数据, Formatting.Indented));
