		for (int i = 0; i < 内充_所有列表.Lines.Length; i++)
		{
			if (!string.IsNullOrWhiteSpace(内充_所有列表.Lines[i]))
			{
				string[] array = 内充_所有列表.Lines[i].Replace(" ", string.Empty).Split("*");
				int result = 1;
				int result2 = 0;
				AllEnums.数值Type 数值Type = AllEnums.数值Type.无;
				if (array.Length >= 2)
				{
					int.TryParse(array[1], out result);
				}
				if (array.Length >= 3)
				{
					int.TryParse(array[2], out result2);
				}
				数值Type = ((array[0] == "金元宝") ? AllEnums.数值Type.金元宝 : ((array[0] == "银元宝") ? AllEnums.数值Type.银元宝 : ((array[0] == "奇宝点") ? AllEnums.数值Type.奇宝点 : ((array[0] == "累充点") ? AllEnums.数值Type.累充点 : ((array[0] == "灵气值") ? AllEnums.数值Type.灵气值 : ((!(array[0] == "金钱")) ? AllEnums.数值Type.道具 : AllEnums.数值Type.金钱))))));
				Singleton<全局变量类>.I.内充支付配置.总奖池.Add(new 内充抽奖类
				{
					名字 = ((数值Type == AllEnums.数值Type.道具) ? array[0] : 数值Type.ToString()),
					数量 = result,
					类型 = 数值Type,
					Is谣言 = (result2 == 1)
				});
			}
		}
		Singleton<全局变量类>.I.验证client.SendRT(10018, 72, JsonConvert.SerializeObject(Singleton<全局变量类>.I.内充支付配置, Formatting.Indented));
